_CHECKPOINT_METADATA_CACHE: dict[str, dict[str, Any]] = {}


def _clone_cached_metadata_value(value: Any) -> Any:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    if isinstance(value, set):
        return set(value)
    if isinstance(value, tuple):
        return tuple(value)
    return value


def checkpoint_is_temporary_artifact_path(checkpoint_path: str | Path | None) -> bool:
    if checkpoint_path is None:
        return False
    checkpoint_name = Path(str(checkpoint_path)).name.lower()
    return any(
        token in checkpoint_name
        for token in (".tmp", "tmp_", "_tmp", "smoke", "probe", "fallbackpromote", "fastprobe", "hotstart")
    )


def get_checkpoint_metadata(checkpoint_path: str | Path | None) -> dict[str, Any] | None:
    resolved_path = resolve_project_path(checkpoint_path)
    if resolved_path is None or not resolved_path.exists():
        return None
    if checkpoint_is_temporary_artifact_path(resolved_path):
        return None
    cache_key = str(resolved_path.resolve())
    cached = _CHECKPOINT_METADATA_CACHE.get(cache_key)
    if cached is not None:
        return {key: _clone_cached_metadata_value(value) for key, value in cached.items()}
    try:
        checkpoint = torch.load(resolved_path, map_location="cpu")
    except Exception as error:
        print(f"Checkpoint metadata probe failed for {resolved_path}: {error}", flush=True)
        _CHECKPOINT_METADATA_CACHE[cache_key] = {"error": str(error)}
        return None
    if not isinstance(checkpoint, dict):
        _CHECKPOINT_METADATA_CACHE[cache_key] = {"error": "not_a_dict"}
        return None
    state_dict = checkpoint.get("model")
    config = checkpoint.get("config")
    key_set = set(state_dict.keys()) if isinstance(state_dict, dict) else set()
    metadata = {
        "resolved_path": resolved_path,
        "config": copy.deepcopy(config) if isinstance(config, dict) else None,
        "state_keys": key_set,
        "has_model_state": bool(key_set),
    }
    _CHECKPOINT_METADATA_CACHE[cache_key] = metadata
    return {key: _clone_cached_metadata_value(value) for key, value in metadata.items()}


# 为低载荷 stage0 自动挑选同结构的高质量恢复参考 checkpoint，避免从随机权重冷启动。
def infer_stage0_hotstart_checkpoint(runtime_config: dict | None) -> str | None:
    if not isinstance(runtime_config, dict):
        return None
    qim_cfg = runtime_config.get("qim", {})
    qim_cfg = qim_cfg if isinstance(qim_cfg, dict) else {}
    if not bool(qim_cfg.get("enabled", False)):
        return None
    target_bpp = resolve_target_bpp(runtime_config)
    if not (0.20 <= float(target_bpp) < 0.40):
        return None
    training_cfg = runtime_config.get("training", {})
    training_cfg = training_cfg if isinstance(training_cfg, dict) else {}
    if not bool(training_cfg.get("stage0_hotstart_enabled", True)):
        return None
    candidate_names = training_cfg.get("stage0_hotstart_candidates")
    if isinstance(candidate_names, str):
        candidate_names = [name.strip() for name in candidate_names.split(",") if name.strip()]
    if not isinstance(candidate_names, list) or not candidate_names:
        candidate_names = [
            "wavebridege_stage2_recovery_refit_v3_stage2_metric_refine.best.pt",
            "wavebridege_div2k_hh_chain_v2_stage2_metric_refine.pt",
            "wavebridege_metric_goal_stage34_v6_stage3b_naturalness_refine.best.pt",
            "wavebridege_div2k_stage3b_stage4_v2_stage3b_naturalness_refine.best.pt",
        ]
    relaxed_runtime_config = copy.deepcopy(runtime_config)
    relaxed_training_cfg = relaxed_runtime_config.setdefault("training", {})
    if isinstance(relaxed_training_cfg, dict):
        relaxed_training_cfg["restore_reference_relaxed_compatibility"] = True
    checkpoint_dir = resolve_project_path("checkpoints")
    if checkpoint_dir is None:
        return None
    resolved_candidates: list[str] = []
    for raw_name in candidate_names:
        resolved_candidate = resolve_project_path(raw_name)
        if resolved_candidate is None or not resolved_candidate.exists():
            resolved_candidate = checkpoint_dir / str(raw_name)
        if resolved_candidate.exists():
            candidate_name = resolved_candidate.name.lower()
            if any(
                token in candidate_name
                for token in (".tmp", "tmp_", "_tmp", "smoke", "probe", "fastprobe", "hotstart")
            ):
                continue
            resolved_candidates.append(str(resolved_candidate))
    for candidate_path in resolved_candidates:
        if not checkpoint_matches_low_payload_polar_runtime(
            candidate_path,
            relaxed_runtime_config,
            allow_cross_bpp_high_quality_base=True,
        ):
            continue
        if checkpoint_matches_restoration_reference_runtime(
            candidate_path,
            relaxed_runtime_config,
            source_checkpoint_path=candidate_path,
        ):
            return candidate_path
    return None


def infer_expected_low_payload_codec_signature(runtime_config: dict | None) -> dict[str, Any]:
    if not isinstance(runtime_config, dict):
        return {}
    qim_cfg = runtime_config.get("qim", {})
    qim_cfg = qim_cfg if isinstance(qim_cfg, dict) else {}
    target_bpp = resolve_target_bpp(runtime_config)
    if not (bool(qim_cfg.get("enabled", False)) and 0.20 <= float(target_bpp) < 0.40):
        return {}
    training_cfg = runtime_config.get("training", {})
    training_cfg = training_cfg if isinstance(training_cfg, dict) else {}
    compressor_cfg = runtime_config.get("compressor", {})
    compressor_cfg = compressor_cfg if isinstance(compressor_cfg, dict) else {}
    preserve_full_codec_structure = bool(
        training_cfg.get("low_payload_preserve_full_codec_structure", False)
        or compressor_cfg.get("preserve_full_codec_structure", False)
    )
    if preserve_full_codec_structure:
        return {}
    return {
        "latent_channels": 6,
        "ll_latent_channels": 4,
        "hf_latent_channels": 2,
        "base_layer_channels": 4,
        "ll_bit_depth": 4,
        "hf_bit_depth": 3,
        "use_rgb_anchor": False,
        "codec_layout_version": "learned_lowfreq_base_v1",
        "bitstream_order": "base_enhancement",
    }


def checkpoint_matches_expected_low_payload_codec_signature(
    checkpoint_path: str | Path | None,
    runtime_config: dict | None,
) -> bool:
    expected_signature = infer_expected_low_payload_codec_signature(runtime_config)
    if not expected_signature:
        return True
    candidate_compressor_cfg = checkpoint_compressor_config(checkpoint_path)
    if not candidate_compressor_cfg:
        return False
    for key, expected_value in expected_signature.items():
        if candidate_compressor_cfg.get(key) != expected_value:
            return False
    candidate_target_bpp = checkpoint_target_bpp(checkpoint_path)
    if candidate_target_bpp is None or not (0.20 <= float(candidate_target_bpp) < 0.40):
        return False
    return True


def checkpoint_matches_low_payload_warmup_signature(
    checkpoint_path: str | Path | None,
    runtime_config: dict | None,
) -> bool:
    if checkpoint_path is None:
        return False
    candidate_compressor_cfg = checkpoint_compressor_config(checkpoint_path)
    if not candidate_compressor_cfg:
        return False
    candidate_target_bpp = checkpoint_target_bpp(checkpoint_path)
    if candidate_target_bpp is None or not (0.20 <= float(candidate_target_bpp) < 0.40):
        return False
    candidate_polar_cfg = checkpoint_polar_config(checkpoint_path)
    if not candidate_polar_cfg:
        return False
    try:
        code_length = int(candidate_polar_cfg.get("code_length", 0))
        info_length = int(candidate_polar_cfg.get("info_length", 0))
        crc_length = int(candidate_polar_cfg.get("crc_length", 16))
    except (TypeError, ValueError):
        return False
    runtime_transmitter_cfg = runtime_config.get("transmitter", {}) if isinstance(runtime_config, dict) else {}
    runtime_transmitter_cfg = runtime_transmitter_cfg if isinstance(runtime_transmitter_cfg, dict) else {}
    runtime_polar_cfg = runtime_transmitter_cfg.get("polar_code", {})
    runtime_polar_cfg = runtime_polar_cfg if isinstance(runtime_polar_cfg, dict) else {}
    expected_info_length = resolve_low_payload_info_length(runtime_config, target_bpp=resolve_target_bpp(runtime_config))
    expected_crc_length = int(runtime_polar_cfg.get("crc_length", 16))
    if code_length != 4096 or info_length != expected_info_length or crc_length != expected_crc_length:
        return False
    if int(candidate_compressor_cfg.get("latent_channels", 0)) != 6:
        return False
    if int(candidate_compressor_cfg.get("ll_latent_channels", 0)) != 4:
        return False
    if int(candidate_compressor_cfg.get("hf_latent_channels", 0)) != 2:
        return False
    if int(candidate_compressor_cfg.get("ll_bit_depth", 0)) < 4:
        return False
    if int(candidate_compressor_cfg.get("hf_bit_depth", 0)) < 3:
        return False
    if bool(candidate_compressor_cfg.get("use_rgb_anchor", True)):
        return False
    if str(candidate_compressor_cfg.get("bitstream_order", "")).strip().lower() != "base_enhancement":
        return False
    return True


def checkpoint_is_compatible_low_payload_recovery_resume(
    checkpoint_path: str | Path | None,
    runtime_config: dict | None,
) -> bool:
    if checkpoint_path is None:
        return False
    candidate_target_bpp = checkpoint_target_bpp(checkpoint_path)
    if candidate_target_bpp is None or not (0.20 <= float(candidate_target_bpp) < 0.40):
        return False
    if not checkpoint_is_joint_recovery_stage(checkpoint_path):
        return False
    if checkpoint_matches_low_payload_warmup_signature(checkpoint_path, runtime_config):
        return False
    if checkpoint_matches_expected_low_payload_codec_signature(checkpoint_path, runtime_config):
        return True
    return checkpoint_matches_low_payload_polar_runtime(
        checkpoint_path,
        runtime_config,
        allow_cross_bpp_high_quality_base=True,
    )


def infer_low_payload_warmup_resume_checkpoint(
    runtime_config: dict | None,
    *,
    requested_stage: str | None = None,
) -> str | None:
    if not isinstance(runtime_config, dict):
        return None
    qim_cfg = runtime_config.get("qim", {})
    qim_cfg = qim_cfg if isinstance(qim_cfg, dict) else {}
    if not bool(qim_cfg.get("enabled", False)):
        return None
    target_bpp = resolve_target_bpp(runtime_config)
    if not (0.20 <= float(target_bpp) < 0.40):
        return None
    checkpoint_dir = resolve_project_path("checkpoints")
    if checkpoint_dir is None:
        return None
    training_cfg = runtime_config.get("training", {})
    training_cfg = training_cfg if isinstance(training_cfg, dict) else {}
    candidate_names = training_cfg.get("low_payload_warmup_resume_candidates")
    if isinstance(candidate_names, str):
        candidate_names = [item.strip() for item in candidate_names.split(",") if item.strip()]
    if not isinstance(candidate_names, list) or not candidate_names:
        candidate_names = [
            "wavebridege_lowpayload_stage2_base_v1_stage0_compressor_warmup.pt",
            "wavebridege_lowpayload_stage2_base_v1_stage0b_receiver_decoder_warmup.pt",
            "wavebridege_lowpayload_stage2_base_v1_stage0c_receiver_frontend_warmup.pt",
        ]

    requested_stage_name = str(requested_stage or "").strip().lower()
    preferred_stage_tokens: tuple[str, ...]
    if requested_stage_name in {"stage1c", "stage2"}:
        preferred_stage_tokens = (
            "stage0c_receiver_frontend_warmup",
            "stage0b_receiver_decoder_warmup",
            "stage0_compressor_warmup",
        )
    else:
        preferred_stage_tokens = (
            "stage0_compressor_warmup",
            "stage0b_receiver_decoder_warmup",
            "stage0c_receiver_frontend_warmup",
        )

    candidate_paths: list[Path] = []
    seen_paths: set[str] = set()

    def add_candidate(candidate_path: Path | None) -> None:
        if candidate_path is None:
            return
        candidate_name = candidate_path.name.lower()
        if any(token in candidate_name for token in (".tmp", "tmp_", "_tmp", "smoke", "probe", "fastprobe", "hotstart")):
            return
        candidate_key = str(candidate_path)
        if candidate_key in seen_paths:
            return
        seen_paths.add(candidate_key)
        candidate_paths.append(candidate_path)

    for raw_name in candidate_names:
        resolved_candidate = resolve_project_path(raw_name)
        if resolved_candidate is None or not resolved_candidate.exists():
            resolved_candidate = checkpoint_dir / str(raw_name)
        if resolved_candidate.exists():
            add_candidate(resolved_candidate)

    for stage_token in preferred_stage_tokens:
        for candidate in checkpoint_dir.glob(f"*{stage_token}*.pt"):
            add_candidate(candidate)
        for candidate in checkpoint_dir.glob(f".*{stage_token}*.pt"):
            add_candidate(candidate)

    filtered_candidates: list[Path] = []
    for candidate_path in candidate_paths:
        if not checkpoint_matches_low_payload_warmup_signature(candidate_path, runtime_config):
            continue
        filtered_candidates.append(candidate_path)

    if not filtered_candidates:
        return None

    priority_rank = {token: index for index, token in enumerate(preferred_stage_tokens)}

    def candidate_sort_key(candidate_path: Path) -> tuple[int, int, str]:
        candidate_name = candidate_path.stem.lower()
        stage_rank = min(
            (priority_rank[token] for token in preferred_stage_tokens if token in candidate_name),
            default=len(preferred_stage_tokens),
        )
        snapshot_rank = 0 if ".best" in candidate_name else 1
        return (stage_rank, snapshot_rank, candidate_name)

    filtered_candidates.sort(key=candidate_sort_key)
    return str(filtered_candidates[0])


def infer_low_payload_joint_bootstrap_checkpoint(
    runtime_config: dict | None,
    *,
    requested_stage: str | None = None,
) -> str | None:
    if not isinstance(runtime_config, dict):
        return None
    qim_cfg = runtime_config.get("qim", {})
    qim_cfg = qim_cfg if isinstance(qim_cfg, dict) else {}
    if not bool(qim_cfg.get("enabled", False)):
        return None
    target_bpp = resolve_target_bpp(runtime_config)
    if not (0.20 <= float(target_bpp) < 0.40):
        return None
    training_cfg = runtime_config.get("training", {})
    training_cfg = training_cfg if isinstance(training_cfg, dict) else {}
    if not bool(training_cfg.get("low_payload_auto_joint_resume", True)):
        return None
    checkpoint_dir = resolve_project_path("checkpoints")
    if checkpoint_dir is None:
        return None

    normalized_stage = str(requested_stage or "").strip().lower()
    stage_priority_map: dict[str, tuple[str, ...]] = {
        "stage1": (
            "stage1_recon_comm_alignment",
            "stage1c_qim_recovery_bridge",
            "stage2_metric_refine",
            "stage3_decoder_release",
            "stage3b_naturalness_refine",
        ),
        "stage1b": (
            "stage1b_qim_bridge",
            "stage1_recon_comm_alignment",
            "stage1c_qim_recovery_bridge",
            "stage2_metric_refine",
            "stage3_decoder_release",
            "stage3b_naturalness_refine",
        ),
        "stage1c": (
            "stage1c_qim_recovery_bridge",
            "stage2_metric_refine",
            "stage1_recon_comm_alignment",
            "stage3_decoder_release",
            "stage3b_naturalness_refine",
        ),
        "stage2": (
            "stage2_metric_refine",
            "stage1c_qim_recovery_bridge",
            "stage3_decoder_release",
            "stage1_recon_comm_alignment",
            "stage3b_naturalness_refine",
        ),
        "stage3": (
            "stage3_decoder_release",
            "stage2_metric_refine",
            "stage1c_qim_recovery_bridge",
            "stage3b_naturalness_refine",
            "stage1_recon_comm_alignment",
        ),
        "stage3b": (
            "stage3b_naturalness_refine",
            "stage3_decoder_release",
            "stage2_metric_refine",
            "stage1c_qim_recovery_bridge",
            "stage1_recon_comm_alignment",
        ),
        "stage4": (
            "stage3b_naturalness_refine",
            "stage3_decoder_release",
            "stage2_metric_refine",
            "stage1c_qim_recovery_bridge",
            "stage1_recon_comm_alignment",
            "stage4_robust_comm_refine",
        ),
    }
    preferred_stage_names = stage_priority_map.get(
        normalized_stage,
        (
            "stage1c_qim_recovery_bridge",
            "stage2_metric_refine",
            "stage3_decoder_release",
            "stage3b_naturalness_refine",
            "stage1_recon_comm_alignment",
        ),
    )

    configured_candidate_names = training_cfg.get("low_payload_joint_resume_candidates")
    if isinstance(configured_candidate_names, str):
        configured_candidate_names = [
            item.strip()
            for item in configured_candidate_names.split(",")
            if item.strip()
        ]
    if not isinstance(configured_candidate_names, list) or not configured_candidate_names:
        configured_candidate_names = [
            "wavebridege_lowpayload_chain_v7_stage3b_naturalness_refine.best.pt",
            "wavebridege_stage2_recovery_refit_v3_stage2_metric_refine.best.pt",
            "wavebridege_div2k_hh_chain_v2_stage2_metric_refine.pt",
        ]

    relaxed_runtime_config = copy.deepcopy(runtime_config)
    relaxed_training_cfg = relaxed_runtime_config.setdefault("training", {})
    if isinstance(relaxed_training_cfg, dict):
        relaxed_training_cfg["restore_reference_relaxed_compatibility"] = True

    candidate_paths: list[Path] = []
    seen_paths: set[str] = set()

    def add_candidate(candidate_path: Path | None) -> None:
        if candidate_path is None:
            return
        candidate_name = candidate_path.name.lower()
        if any(
            token in candidate_name
            for token in (".tmp", "tmp_", "_tmp", "smoke", "probe", "fastprobe", "hotstart")
        ):
            return
        candidate_key = str(candidate_path)
        if candidate_key in seen_paths:
            return
        seen_paths.add(candidate_key)
        candidate_paths.append(candidate_path)

    for raw_name in configured_candidate_names:
        resolved_candidate = resolve_project_path(raw_name)
        if resolved_candidate is None or not resolved_candidate.exists():
            resolved_candidate = checkpoint_dir / str(raw_name)
        if resolved_candidate.exists():
            add_candidate(resolved_candidate)

    for stage_name in preferred_stage_names:
        for candidate in checkpoint_dir.glob(f"*{stage_name}*.pt"):
            add_candidate(candidate)
        for candidate in checkpoint_dir.glob(f".*{stage_name}*.pt"):
            add_candidate(candidate)
    for candidate in checkpoint_dir.glob("*lowpayload*.pt"):
        add_candidate(candidate)
    for candidate in checkpoint_dir.glob(".*lowpayload*.pt"):
        add_candidate(candidate)

    filtered_candidates: list[Path] = []
    explicit_low_payload_allowlist = {
        str(item).lower().replace(".pt", "")
        for item in configured_candidate_names
    }
    for candidate_path in candidate_paths:
        candidate_name = candidate_path.stem.lower()
        candidate_target_bpp = checkpoint_target_bpp(candidate_path)
        if candidate_target_bpp is None or not (0.20 <= float(candidate_target_bpp) < 0.40):
            continue
        if normalized_stage in {"stage1", "stage1b", "stage1c", "stage2"} and not checkpoint_matches_expected_low_payload_codec_signature(
            candidate_path,
            runtime_config,
        ):
            continue
        if explicit_low_payload_allowlist and not any(
            allowed_name in candidate_name for allowed_name in explicit_low_payload_allowlist
        ):
            continue
        if "stage4_robust_comm_refine" in candidate_name and normalized_stage != "stage4":
            continue
        if not (
            checkpoint_is_joint_recovery_stage(candidate_path)
            or checkpoint_is_high_metric_resume_candidate(candidate_path)
        ):
            continue
        if not (
            checkpoint_matches_restoration_reference_runtime(
                candidate_path,
                relaxed_runtime_config,
                source_checkpoint_path=candidate_path,
            )
            or allow_low_payload_restore_reference_candidate(
                candidate_path,
                relaxed_runtime_config,
                source_checkpoint_path=candidate_path,
            )
        ):
            continue
        if not checkpoint_matches_low_payload_polar_runtime(
            candidate_path,
            relaxed_runtime_config,
            allow_cross_bpp_high_quality_base=True,
        ):
            continue
        filtered_candidates.append(candidate_path)

    if not filtered_candidates:
        return None

    priority_rank = {stage_name: index for index, stage_name in enumerate(preferred_stage_names)}
    known_rank = {
        name.lower(): index
        for index, name in enumerate(str(item).lower() for item in configured_candidate_names)
    }

    def candidate_sort_key(candidate_path: Path) -> tuple[int, int, int, int, int, str]:
        candidate_name = candidate_path.stem.lower()
        low_payload_stage_rank = low_payload_restore_reference_stage_rank(candidate_name)
        stage_rank = min(
            (priority_rank[stage_name] for stage_name in preferred_stage_names if stage_name in candidate_name),
            default=len(preferred_stage_names),
        )
        snapshot_rank = 1
        if ".best" in candidate_name:
            snapshot_rank = 0
        elif ".fallback" in candidate_name:
            snapshot_rank = 2
        temporary_rank = 1 if any(
            token in candidate_name for token in ("smoke", "probe", "tmp_", ".tmp", "hotstart", "fastprobe")
        ) else 0
        explicit_rank = min(
            (
                configured_rank
                for configured_name, configured_rank in known_rank.items()
                if configured_name.replace(".pt", "") in candidate_name
            ),
            default=len(known_rank),
        )
        return (
            low_payload_stage_rank,
            stage_rank,
            snapshot_rank,
            explicit_rank,
            temporary_rank,
            candidate_name,
        )

    filtered_candidates.sort(key=candidate_sort_key)
    return str(filtered_candidates[0])


class TeeLogger:
    # 将终端输出同步写入日志文件，方便服务器长时间训练后回看完整记录。
    def __init__(self, *streams) -> None:
        self.streams = streams

    # 同时写入终端和日志文件。
    def write(self, data: str) -> int:
        written = 0
        for stream in self.streams:
            try:
                if getattr(stream, "closed", False):
                    continue
                stream.write(data)
                stream.flush()
                written = len(data)
            except Exception:
                continue
        return written

    # 刷新所有输出流，确保日志实时落盘。
    def flush(self) -> None:
        for stream in self.streams:
            try:
                if getattr(stream, "closed", False):
                    continue
                stream.flush()
            except Exception:
                continue


# 返回是否处于 torchrun 启动的分布式训练上下文。
def is_distributed_training() -> bool:
    return int(os.environ.get("WORLD_SIZE", "1")) > 1


# 返回当前进程的全局 rank。
def get_rank() -> int:
    return int(os.environ.get("RANK", "0"))


# 返回当前进程是否为主进程，主进程负责日志、保存和最终评估。
def is_main_process() -> bool:
    return get_rank() == 0


# 解包 DDP 包装后的真实模块，方便访问子模块和保存无前缀权重。
def unwrap_module(module: nn.Module | None) -> nn.Module | None:
    if module is None:
        return None
    return module.module if hasattr(module, "module") else module


def enforce_trainable_scope_mode(model: nn.Module, training_cfg: dict) -> None:
    # 对只微调小模块的阶段锁住主链路训练态，防止冻结模块的运行统计被单批次污染。
    root_model = unwrap_module(model)
    if root_model is None:
        return
    apply_low_payload_stage4_forced_trainable_scope(training_cfg)
    scope = str(training_cfg.get("trainable_scope", "") or "").strip().lower()
    isolated_scopes = {
        "stego_naturalizer",
        "carrier_prior_to_image",
        "carrier_prior_to_image_last",
        "carrier_prior_to_image_and_stego_naturalizer",
        "carrier_prior_and_payload_embedder_and_receiver_refine_and_robust_comm_decoder",
        "receiver_external_llr_frontend",
        "receiver_external_llr_scale_only",
        "receiver_external_llr_adapter_only",
        "receiver_comm_decoder_light",
        "receiver_refine_and_robust_comm_decoder",
        "receiver_robust_comm_decoder",
        "receiver_comm_decoder",
        "payload_embedder_and_receiver_comm_decoder",
        "payload_embedder_and_receiver_refine_and_robust_comm_decoder",
    }
    if scope not in isolated_scopes:
        return
    root_model.eval()
    if hasattr(root_model, "stego_naturalizer"):
        root_model.stego_naturalizer.train(
            scope in {"stego_naturalizer", "carrier_prior_to_image_and_stego_naturalizer"}
        )
    if scope in {"carrier_prior_to_image", "carrier_prior_to_image_last", "carrier_prior_to_image_and_stego_naturalizer"}:
        prior_generator = getattr(getattr(root_model, "generator", None), "prior_generator", None)
        to_image = getattr(prior_generator, "to_image", None)
        if to_image is not None:
            to_image.train()
    if scope == "carrier_prior_and_payload_embedder_and_receiver_refine_and_robust_comm_decoder":
        prior_generator = getattr(getattr(root_model, "generator", None), "prior_generator", None)
        if prior_generator is not None:
            prior_generator.train()
    if scope in {
        "carrier_prior_and_payload_embedder_and_receiver_refine_and_robust_comm_decoder",
        "payload_embedder_and_receiver_comm_decoder",
        "payload_embedder_and_receiver_refine_and_robust_comm_decoder",
    }:
        payload_embedder = getattr(getattr(root_model, "generator", None), "payload_embedder", None)
        if payload_embedder is not None:
            payload_embedder.train()
    if scope in {
        "carrier_prior_and_payload_embedder_and_receiver_refine_and_robust_comm_decoder",
        "receiver_refine_and_robust_comm_decoder",
        "receiver_external_llr_frontend",
        "receiver_external_llr_scale_only",
        "receiver_external_llr_adapter_only",
        "receiver_comm_decoder_light",
        "receiver_robust_comm_decoder",
        "receiver_comm_decoder",
        "payload_embedder_and_receiver_comm_decoder",
        "payload_embedder_and_receiver_refine_and_robust_comm_decoder",
    }:
        receiver = getattr(root_model, "receiver", None)
        if receiver is None:
            return
        if scope == "receiver_external_llr_frontend":
            receiver_modules = [
                getattr(receiver, "robust_external_llr_adapter", None),
                getattr(receiver, "robust_external_symbol_calibrator", None),
            ]
        elif scope == "receiver_external_llr_scale_only":
            receiver_modules = [
                getattr(receiver, "robust_external_llr_adapter", None),
            ]
        elif scope == "receiver_external_llr_adapter_only":
            receiver_modules = [
                getattr(receiver, "robust_external_llr_adapter", None),
            ]
        elif scope == "receiver_comm_decoder_light":
            receiver_modules = [
                getattr(receiver, "external_llr_adapter", None),
                getattr(receiver, "symbol_calibrator", None),
                getattr(receiver, "block_token_norm", None),
                getattr(receiver, "block_token_proj", None),
                getattr(receiver, "mamba", None),
            ]
        elif scope == "receiver_robust_comm_decoder":
            receiver_modules = [
                getattr(receiver, "robust_external_llr_adapter", None),
                getattr(receiver, "robust_external_symbol_calibrator", None),
                getattr(receiver, "block_token_norm", None),
                getattr(receiver, "block_token_proj", None),
                getattr(receiver, "mamba", None),
                getattr(receiver, "bp_decoder", None),
            ]
        elif scope == "receiver_refine_and_robust_comm_decoder":
            image_refiner = getattr(receiver, "image_refiner", None)
            if image_refiner is not None:
                image_refiner.train()
            receiver_modules = [
                getattr(receiver, "robust_external_llr_adapter", None),
                getattr(receiver, "robust_external_symbol_calibrator", None),
                getattr(receiver, "block_token_norm", None),
                getattr(receiver, "block_token_proj", None),
                getattr(receiver, "mamba", None),
                getattr(receiver, "bp_decoder", None),
            ]
        elif scope in {
            "payload_embedder_and_receiver_refine_and_robust_comm_decoder",
            "carrier_prior_and_payload_embedder_and_receiver_refine_and_robust_comm_decoder",
        }:
            image_refiner = getattr(receiver, "image_refiner", None)
            if image_refiner is not None:
                image_refiner.train()
            receiver_modules = [
                getattr(receiver, "robust_external_llr_adapter", None),
                getattr(receiver, "robust_external_symbol_calibrator", None),
                getattr(receiver, "block_token_norm", None),
                getattr(receiver, "block_token_proj", None),
                getattr(receiver, "mamba", None),
                getattr(receiver, "bp_decoder", None),
            ]
        else:
            receiver_modules = [
                getattr(receiver, "external_llr_adapter", None),
                getattr(receiver, "symbol_calibrator", None),
                getattr(receiver, "block_token_norm", None),
                getattr(receiver, "block_token_proj", None),
                getattr(receiver, "mamba", None),
                getattr(receiver, "bp_decoder", None),
            ]
        if not getattr(root_model, "qim_enabled", False):
            receiver_modules.extend(
                [
                    getattr(receiver, "despreader", None),
                    getattr(receiver, "llr_scaler", None),
                ]
            )
        for module in receiver_modules:
            if module is not None:
                module.train()


# 按轮次渐进打开接收端图像细化强度，避免新恢复分支从旧检查点续训时突然破坏恢复图。
def apply_receiver_refine_strength_schedule(
    model: nn.Module,
    training_cfg: dict,
    epoch_index: int | None = None,
) -> float | None:
    root_model = unwrap_module(model)
    receiver = getattr(root_model, "receiver", None)
    if receiver is None or not hasattr(receiver, "image_refine_strength"):
        return None
    target_strength = float(
        training_cfg.get(
            "image_refine_strength_target",
            getattr(receiver, "image_refine_strength", 0.0),
        )
    )
    target_strength = max(0.0, target_strength)
    warmup_epochs = max(0, int(training_cfg.get("image_refine_strength_warmup_epochs", 0) or 0))
    if warmup_epochs <= 0:
        receiver.image_refine_strength = target_strength
        return target_strength
    start_strength = float(training_cfg.get("image_refine_strength_warmup_start", min(0.08, target_strength)))
    start_strength = max(0.0, min(target_strength, start_strength))
    if epoch_index is None:
        scheduled_strength = start_strength
    else:
        progress = min(1.0, max(0.0, float(epoch_index + 1) / float(warmup_epochs)))
        scheduled_strength = start_strength + (target_strength - start_strength) * progress
    receiver.image_refine_strength = scheduled_strength
    return scheduled_strength


