def checkpoint_contains_model_keys(
    checkpoint_path: str | Path | None,
    required_keys: tuple[str, ...],
) -> bool:
    metadata = get_checkpoint_metadata(checkpoint_path)
    if metadata is None:
        return False
    available_keys = metadata.get("state_keys")
    if not isinstance(available_keys, set):
        return False
    for key in required_keys:
        if key in available_keys or f"module.{key}" in available_keys:
            continue
        return False
    return True


# 判断检查点文件名是否已经来自联合恢复阶段，避免把 stage1 续训点误当成 stage0 预训练点。
def checkpoint_is_joint_recovery_stage(checkpoint_path: str | Path | None) -> bool:
    if checkpoint_path is None:
        return False
    checkpoint_stem = Path(str(checkpoint_path)).stem.lower()
    joint_stage_names = (
        "stage1b_qim_bridge",
        "stage1_recon_comm_alignment",
        "stage2_metric_refine",
        "stage3_decoder_release",
        "stage3b_naturalness_refine",
        "stage1c_qim_recovery_bridge",
        "stage4_robust_comm_refine",
    )
    return any(stage_name in checkpoint_stem for stage_name in joint_stage_names)


# 根据检查点内部配置识别已经具备高恢复指标的可续训模型，避免只靠文件名误判续训阶段。
def checkpoint_is_high_metric_resume_candidate(checkpoint_path: str | Path | None) -> bool:
    resolved_path = resolve_project_path(checkpoint_path)
    if resolved_path is None or not resolved_path.exists():
        return False
    checkpoint_stem = Path(str(resolved_path)).stem.lower()
    if "stage0" in checkpoint_stem:
        return False
    metadata = get_checkpoint_metadata(resolved_path)
    if metadata is None:
        return False
    available_keys = metadata.get("state_keys")
    config = metadata.get("config")
    if not isinstance(available_keys, set) or not available_keys:
        return False
    if not isinstance(config, dict):
        return False
    qim_enabled = bool(config.get("qim", {}).get("enabled", False))
    try:
        target_bpp = float(config.get("transmitter", {}).get("target_bpp", 0.0) or 0.0)
    except (TypeError, ValueError):
        target_bpp = 0.0
    dataset_name = str(config.get("datasets", {}).get("active", "")).lower().strip()
    if not qim_enabled or target_bpp < 0.25:
        return False
    if dataset_name and dataset_name not in {"div2k", "alaska2", "bossbase", "landscape"}:
        return False
    trainable_scope = str(config.get("training", {}).get("trainable_scope", "")).lower().strip()
    allowed_joint_scopes = {
        "receiver_image_refiner",
        "receiver_image_refiner_and_compressor_post",
        "receiver_image_refiner_and_compressor_decoder",
        "receiver_image_refiner_and_compressor_decoder_and_comm",
        "receiver_image_refiner_and_compressor_recon_heads",
        "receiver_image_refiner_and_compressor_wavelet_heads",
        "receiver_image_refiner_and_compressor_wavelet_heads_and_post",
        "receiver_latent_bridge_and_compressor_decoder",
        "receiver_latent_bridge_and_compressor_decoder_and_refiner",
        "receiver_recovery_bridge_and_compressor_decoder_and_refiner",
        "receiver_latent_bridge_and_compressor_wavelet_heads_and_refiner",
        "receiver_latent_bridge_and_image_refiner",
        "receiver_latent_bridge",
        "carrier_prior_generator",
        "carrier_prior_to_image",
        "carrier_prior_to_image_and_stego_naturalizer",
        "payload_embedder",
        "carrier_prior_and_receiver_image_refiner",
        "carrier_prior_and_receiver_image_refiner_and_compressor_post",
        "carrier_prior_and_receiver_latent_bridge",
        "carrier_prior_and_payload_embedder",
        "carrier_prior_and_payload_embedder_and_receiver_comm_decoder",
        "carrier_prior_and_payload_embedder_and_receiver_refine_and_comm_decoder",
        "payload_embedder_and_receiver_refine_and_compressor_decoder_and_comm",
        "payload_embedder_and_receiver_comm_decoder",
        "payload_embedder_and_receiver_refine_and_comm_decoder",
        "payload_embedder_and_receiver_refine_and_robust_comm_decoder",
        "receiver_external_llr_frontend",
        "receiver_external_llr_adapter_only",
        "receiver_comm_decoder_light",
        "receiver_refine_and_robust_comm_decoder",
        "receiver_robust_comm_decoder",
        "receiver_comm_decoder",
        "stego_naturalizer",
    }
    if not checkpoint_is_joint_recovery_stage(resolved_path) and trainable_scope not in allowed_joint_scopes:
        return False
    high_metric_keys = (
        "compressor.ll_stem.0.block.0.weight",
        "compressor.decoder_fusion.0.block.0.weight",
        "receiver.image_refiner.feature_tower.0.block.0.weight",
        "generator.prior_generator.noise_proj.weight",
    )
    return any(key in available_keys or f"module.{key}" in available_keys for key in high_metric_keys)


