def normalize_low_payload_stage4_robustness_profile(profile: str | None) -> str:
    normalized = str(profile or "standard").strip().lower()
    if normalized not in LOW_PAYLOAD_STAGE4_ROBUSTNESS_PROFILES:
        return "standard"
    return normalized


def resolve_low_payload_stage4_robustness_profile(training_cfg: dict | None) -> str:
    if isinstance(training_cfg, dict):
        return normalize_low_payload_stage4_robustness_profile(
            training_cfg.get("low_payload_stage4_robustness_profile", "standard")
        )
    return "standard"


def low_payload_stage4_profile_uses_sprint_defaults(profile: str | None) -> bool:
    normalized = normalize_low_payload_stage4_robustness_profile(profile)
    return normalized in {"sprint", "warroom24h"}


def low_payload_stage4_profile_is_warroom24h(profile: str | None) -> bool:
    return normalize_low_payload_stage4_robustness_profile(profile) == "warroom24h"


def normalize_low_payload_stage4_mode(mode: str | None) -> str | None:
    normalized = str(mode or "").strip().lower()
    if normalized not in LOW_PAYLOAD_STAGE4_MODE_CHOICES:
        return None
    return normalized


def low_payload_stage4_decoder_mode_forced(training_cfg: dict | None = None) -> bool:
    """Return True when the caller explicitly requested the decoder-first route."""
    env_mode = normalize_low_payload_stage4_mode(os.environ.get("LOW_PAYLOAD_STAGE4_MODE"))
    cfg_mode = normalize_low_payload_stage4_mode(
        (training_cfg or {}).get("low_payload_stage4_mode") if isinstance(training_cfg, dict) else None
    )
    return bool(env_mode == "decoder" or cfg_mode == "decoder")


def low_payload_stage4_decoder_qim_profile(training_cfg: dict | None = None) -> str:
    raw_profile = os.environ.get(
        "WAVEBRIDEGE_STAGE4_DECODER_QIM_PROFILE",
        (training_cfg or {}).get("stage4_decoder_qim_profile", "strong"),
    )
    normalized = str(raw_profile or "strong").strip().lower().replace("-", "_")
    if normalized in {"medium", "learnable"}:
        return "mid"
    if normalized in {"spread", "spread_dct", "dct_spread", "jpeg_spread"}:
        return "spread_dct"
    if normalized in {"spread_wavelet", "wavelet_spread", "multiband", "multi_band"}:
        return "spread_wavelet"
    if normalized in {"parity_y", "y_parity", "jpeg_parity_y", "robust_parity_y"}:
        return "parity_y"
    if normalized in {"hybrid_parity_y", "parity_y_hybrid", "robust_aux_parity_y", "parity_y_aux"}:
        return "hybrid_parity_y"
    if normalized not in {"strong", "mid"}:
        return "strong"
    return normalized


def low_payload_stage4_robust_aux_embed_alpha(training_cfg: dict | None = None) -> float:
    raw_value = os.environ.get(
        "WAVEBRIDEGE_STAGE4_ROBUST_AUX_EMBED_ALPHA",
        (training_cfg or {}).get("stage4_robust_aux_embed_alpha", 1.0),
    )
    try:
        value = float(raw_value)
    except (TypeError, ValueError):
        value = 1.0
    if not math.isfinite(value):
        value = 1.0
    return float(max(0.0, min(1.0, value)))


def _decoder_qim_env_prefix(profile: str) -> str:
    normalized = str(profile or "").strip().upper().replace("-", "_")
    normalized = normalized.replace("PARITY_Y_HYBRID", "HYBRID_PARITY_Y")
    return f"WAVEBRIDEGE_STAGE4_DECODER_{normalized}"


def _stage4_env_str_choice(name: str, current: str, allowed: set[str] | None = None) -> str:
    raw_value = os.environ.get(name)
    if raw_value is None or str(raw_value).strip() == "":
        return str(current)
    value = str(raw_value).strip().lower()
    if allowed is not None and value not in allowed:
        return str(current)
    return value


def _apply_decoder_qim_env_overrides(profile: str, cfg: dict) -> dict:
    prefix = _decoder_qim_env_prefix(profile)
    cfg = copy.deepcopy(cfg)
    if cfg.get("domain", "dct") == "dct":
        cfg["dct_channels"] = _stage4_env_str_choice(
            f"{prefix}_DCT_CHANNELS",
            str(cfg.get("dct_channels", "y")),
            {"y", "ycbcr"},
        )
        cfg["dct_coefficients"] = _stage4_env_str_choice(
            f"{prefix}_DCT_COEFFICIENTS",
            str(cfg.get("dct_coefficients", "auto32")),
            None,
        )
        cfg["dct_quant_scale"] = _stage4_env_float_override(
            f"{prefix}_QUANT_SCALE",
            float(cfg.get("dct_quant_scale", 1.0)),
            min_value=0.05,
            max_value=2.0,
        )
    cfg["delta"] = _stage4_env_float_override(
        f"{prefix}_DELTA",
        float(cfg.get("delta", 1.0)),
        min_value=0.05,
        max_value=2.0,
    )
    cfg["strength"] = _stage4_env_float_override(
        f"{prefix}_STRENGTH",
        float(cfg.get("strength", 1.0)),
        min_value=0.05,
        max_value=2.0,
    )
    cfg["llr_scale"] = _stage4_env_float_override(
        f"{prefix}_LLR_SCALE",
        float(cfg.get("llr_scale", 52.0)),
        min_value=1.0,
        max_value=96.0,
    )
    cfg["llr_clamp"] = _stage4_env_float_override(
        f"{prefix}_LLR_CLAMP",
        float(cfg.get("llr_clamp", 40.0)),
        min_value=1.0,
        max_value=96.0,
    )
    cfg["repetition_factor"] = _stage4_env_int_override(
        f"{prefix}_REPETITION",
        int(cfg.get("repetition_factor", 1) or 1),
        min_value=1,
        max_value=9,
    )
    if "embed_alpha" in cfg:
        cfg["embed_alpha"] = _stage4_env_float_override(
            f"{prefix}_EMBED_ALPHA",
            float(cfg.get("embed_alpha", low_payload_stage4_robust_aux_embed_alpha())),
            min_value=0.0,
            max_value=1.0,
        )
    return cfg


