# 将 codec 的完整 latent bit 数对齐到目标 bpp 内，避免训练了但真实链路永远传不完的截断尾部。
def align_codec_capacity_to_target_bpp(config: dict) -> None:
    data_cfg = config.get("data", {})
    compressor_cfg = config.setdefault("compressor", {})
    transmitter_cfg = config.setdefault("transmitter", {})
    target_bpp = transmitter_cfg.get("target_bpp")
    if target_bpp is None or float(target_bpp) <= 0:
        return

    preserve_full_codec_structure = bool(compressor_cfg.get("preserve_full_codec_structure", False))
    if preserve_full_codec_structure:
        ll_channels = max(1, int(compressor_cfg.get("ll_latent_channels", max(1, int(compressor_cfg.get("latent_channels", 4)) - 1))))
        hf_channels = max(
            0,
            int(
                compressor_cfg.get(
                    "hf_latent_channels",
                    max(0, int(compressor_cfg.get("latent_channels", ll_channels)) - ll_channels),
                )
            ),
        )
        compressor_cfg["ll_latent_channels"] = ll_channels
        compressor_cfg["hf_latent_channels"] = hf_channels
        compressor_cfg["latent_channels"] = ll_channels + hf_channels
        compressor_cfg["base_layer_channels"] = min(
            int(compressor_cfg.get("base_layer_channels", ll_channels)),
            compressor_cfg["latent_channels"],
        )
        return

    image_size = int(data_cfg.get("image_size", 512))
    downsample_stages = max(1, int(compressor_cfg.get("downsample_stages", 3)))
    latent_side = max(1, image_size // (2 ** (downsample_stages + 1)))
    latent_positions = max(1, latent_side * latent_side)
    target_bits = int(math.floor(float(target_bpp) * max(1, image_size * image_size)))
    bits_per_position_budget = max(1, target_bits // latent_positions)

    bit_depth = int(transmitter_cfg.get("bit_depth", 4))
    ll_bit_depth = int(compressor_cfg.get("ll_bit_depth", bit_depth))
    hf_bit_depth = int(compressor_cfg.get("hf_bit_depth", bit_depth))
    ll_channels = int(compressor_cfg.get("ll_latent_channels", 4))
    hf_channels = int(compressor_cfg.get("hf_latent_channels", 1))
    full_bits_per_position = ll_channels * ll_bit_depth + hf_channels * hf_bit_depth
    full_latent_bits = latent_positions * full_bits_per_position
    partial_overhead = float(compressor_cfg.get("max_partial_latent_overhead", 1.0))
    if full_bits_per_position <= bits_per_position_budget or (
        partial_overhead > 1.0 and full_latent_bits <= int(math.ceil(target_bits * partial_overhead))
    ):
        compressor_cfg["latent_channels"] = ll_channels + hf_channels
        compressor_cfg["base_layer_channels"] = min(
            int(compressor_cfg.get("base_layer_channels", ll_channels)),
            compressor_cfg["latent_channels"],
        )
        return

    fitted_ll_channels = min(ll_channels, max(1, bits_per_position_budget // max(1, ll_bit_depth)))
    remaining_bits = max(0, bits_per_position_budget - fitted_ll_channels * ll_bit_depth)
    fitted_hf_channels = min(hf_channels, remaining_bits // max(1, hf_bit_depth))
    if fitted_hf_channels <= 0 and fitted_ll_channels > 1 and bits_per_position_budget >= hf_bit_depth:
        candidate_ll_channels = fitted_ll_channels - 1
        candidate_hf_channels = (bits_per_position_budget - candidate_ll_channels * ll_bit_depth) // max(1, hf_bit_depth)
        if candidate_hf_channels > 0:
            fitted_ll_channels = candidate_ll_channels
            fitted_hf_channels = min(hf_channels, candidate_hf_channels)

    compressor_cfg["ll_latent_channels"] = max(1, int(fitted_ll_channels))
    compressor_cfg["hf_latent_channels"] = max(0, int(fitted_hf_channels))
    compressor_cfg["latent_channels"] = compressor_cfg["ll_latent_channels"] + compressor_cfg["hf_latent_channels"]
    compressor_cfg["base_layer_channels"] = min(
        int(compressor_cfg.get("base_layer_channels", compressor_cfg["ll_latent_channels"])),
        compressor_cfg["latent_channels"],
    )


